# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TÜRK-İSLAM MEDENİYETİNDE EĞİTİM: NİZÂMİYE VE ANADOLU MEDRESELERİ</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">NİZÂMİYE MEDRESELERİ (1067 - BAĞDAT)</text>\n  <text x="34" y="85" font-size="11.2" fill="#1e3a8a">• Kurucu: Büyük Selçuklu Veziri Nizâmülmülk (Burslu/Yatılı).</text>\n  <text x="34" y="110" font-size="11.2" fill="#1e3a8a">• Amaç 1: Nitelikli devlet memuru, kadı ve müderris yetiştirmek.</text>\n  <text x="34" y="135" font-size="11.2" fill="#1e3a8a">• Amaç 2: Bâtıni (Haşhaşî) faaliyetlere karşı fikrî mücadele.</text>\n  <text x="34" y="160" font-size="11.2" fill="#1e3a8a">• Müfredat: Dinî (naklî) ilimler + Aklî (tıp, astronomi, matematik).</text>\n  <text x="34" y="185" font-size="11.2" fill="#1e3a8a">• Ünlü Müderrisi: İmam Gazâlî | Diploma: İcâzetnâme.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">ANADOLU\'DAKİ ÖNCÜ MEDRESE VE DARÜŞŞİFALAR</text>\n  <text x="370" y="85" font-size="11.2" fill="#78350f">• İlk Anadolu Medresesi: Niksar Yağıbasan Medresesi (Danişment).</text>\n  <text x="370" y="110" font-size="11.2" fill="#78350f">• İlk Tıp Medresesi: Kayseri Gevher Nesibe Darüşşifası (1206).</text>\n  <text x="370" y="135" font-size="11.2" fill="#78350f">• Astronomi/Rasathane: Kırşehir Cacabey Medresesi.</text>\n  <text x="370" y="160" font-size="11.2" fill="#78350f">• Konya: Karatay Medresesi, İnce Minareli, Sırçalı Medrese.</text>\n  <text x="370" y="185" font-size="11.2" fill="#78350f">• Sivas ve Erzurum: Gök Medrese, Buruciye, Çifte Minareli.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Orta Çağ\'da Batı\'da akıl hastaları yakılırken, Selçuklu darüşşifalarında hastalar su sesi ve müzikle tedavi edilmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">1040-1299 DÖNEMİ BİLİM İNSANLARI, DÜŞÜNÜRLER VE MUTASAVVIFLAR</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">BİLİM, DİL VE TARİH ÂLİMLERİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#14532d">• Kaşgarlı Mahmud: Dîvânu Lugâti\'t-Türk (İlk Türkçe sözlük).</text>\n  <text x="34" y="110" font-size="11.2" fill="#14532d">• Ömer Hayyam: İsfahan Rasathanesi, Celâlî Takvimi ve Cebir.</text>\n  <text x="34" y="135" font-size="11.2" fill="#14532d">• El-Cezerî (Artuklu): Sibernetik/Robotik kurucusu (Kitâbü\'l-Hiyel).</text>\n  <text x="34" y="160" font-size="11.2" fill="#14532d">• Nizâmülmülk: Siyâsetnâme (Devlet yönetimi rehberi).</text>\n  <text x="34" y="185" font-size="11.2" fill="#14532d">• İbn Bîbî: el-Evâmirü\'l-Alâiyye (Türkiye Selçuklu tarihi).</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">GÖNÜL MİMARLARI (MUTASAVVIFLAR)</text>\n  <text x="370" y="85" font-size="11.2" fill="#1e3a8a">• Hoca Ahmed Yesevî: Dîvân-ı Hikmet (Pîr-i Türkistan).</text>\n  <text x="370" y="110" font-size="11.2" fill="#1e3a8a">• İbnü\'l-Arabî: Ekberîlik ve Vahdet-i Vücûd düşüncesi.</text>\n  <text x="370" y="135" font-size="11.2" fill="#1e3a8a">• Mevlânâ Celâleddîn-i Rûmî: Mesnevî, Dîvân-ı Kebîr (Konya).</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• Hacı Bektaş Velî: Makâlât (Horasan ereni, Sulucakarahöyük).</text>\n  <text x="370" y="185" font-size="11.2" fill="#1e3a8a">• Yunus Emre: Risâletü\'n-Nushiyye ve Dîvân (Türkçe tasavvuf).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Alperenler ve mutasavvıflar, kılıçla fethedilen Anadolu topraklarını sevgi, hoşgörü ve ahlakla vatanlaştırmıştır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TÜRK-İSLAM MİMARİSİ VE SANAT DALLARI (1040-1299)</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">MİMARİ YAPI TÜRLERİ VE ÖRNEKLERİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#581c87">• Külliye: Cami merkezli sosyal-eğitim yapı kompleksi.</text>\n  <text x="34" y="110" font-size="11.2" fill="#581c87">• Darüşşifa: Hastane ve tıp okulu (Gevher Nesibe, Divriği).</text>\n  <text x="34" y="135" font-size="11.2" fill="#581c87">• Kervansaray (Sultan Han): Ticaret yollarında güvenli konaklama.</text>\n  <text x="34" y="160" font-size="11.2" fill="#581c87">• Kümbet: Çadır (otağ) mimarisini yansıtan konik çatılı anıt mezar.</text>\n  <text x="34" y="185" font-size="11.2" fill="#581c87">• Şaheser: Divriği Ulu Camii ve Darüşşifası (Mengücekliler).</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">SÜSLEME SANATLARI VE ANADOLU\'YA ETKİSİ</text>\n  <text x="370" y="85" font-size="11.2" fill="#7c2d12">• Taş İşçiliği: Anıtsal taçkapılar ve mukarnas (sarkıt) süsleme.</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• Çini ve Keramik: İç mekânlarda turkuaz ve kobalt mavisi çini.</text>\n  <text x="370" y="135" font-size="11.2" fill="#7c2d12">• El Sanatları: Hat (yazı), Tezhip (yaldızlama), Minyatür, Halıcılık.</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Semboller: Geometrik yıldızlar, rumî motif ve çift başlı kartal.</text>\n  <text x="370" y="185" font-size="11.2" fill="#7c2d12">• Tarihsel Etki: Mimari eserler Anadolu\'nun tapu senedi olmuştur.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Türkistan\'daki otağ (çadır) kültürü mimaride \'kümbet\' yapılarına, \'ribat\' geleneği ise \'kervansaraylara\' dönüşmüştür.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
